import { globalattrDetail, globalattrSave } from "@/api/system/relationManage";
import { getDictList as _getDictList, getDictCmdbList as _getDictCmdbList } from "@/api/dict";
import subSelect from "@/components/subSelect";
import { selectSwitches, queryIpPoolCount, updateSubnet } from "@/api/operation/safeaccess/subnet";
export default {
  props: ['isShow', 'arrtId'],
  components: {
    subSelect: subSelect
  },
  data: function data() {
    return {
      isSaveWDBG: true,
      orgCodeList: [],
      swStateList: [],
      snmpVersionList: [],
      Is802List: [],
      isAccessSwitchList: [],
      brandList: [],
      seriesList: [],
      deviceModelList: [],
      maintenanceCountryList: [],
      searchForm: {
        ipAvailableCount: undefined
      },
      rules: {
        name: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }]
      },
      pageLoading: false,
      saveLoading: false,
      dataList: [],
      selectionList: [],
      total: 0,
      tableLoading: false,
      //表格加载
      tableHeight: undefined
    };
  },
  computed: {
    // ids() {
    //   let ids = [];
    //   this.selectionList.forEach(ele => {
    //     ids.push(ele.id);
    //   });
    //   return ids.join(",");
    // },
  },
  created: function created() {
    //加载字典--工单状态
    // //加载字典--WBS元素
    this.getDictList("is3");
    //加载字典--入库仓库
    this.getDictList("swState");
    //加载字典--i6000同步状态
    this.getDictList("snmpVersion");
    //加载字典--WBS项目
    this.getDictList("Is802");
    //加载字典--i6000同步状态
    this.getDictList("isAccessSwitch");

    // 加载字典
    this.getDictCmdbList('1082554947272704'); // 品牌
    this.getDictCmdbList('1082609011851264'); // 系列
    this.getDictCmdbList('1082608047161344'); // 型号
    this.getDictCmdbList('1083979207081984'); // 国家及地区
  },
  methods: {
    //判断该子网下是否有交换机信息
    searchSwitchBySubnetId: function searchSwitchBySubnetId() {
      var _this = this;
      selectSwitches({
        subentId: this.searchForm.subnetOld
      }).then(function (resp) {
        if (resp.data) {
          _this.$message({
            message: '该子网下存在交换机，请执行退网操作后，再进行网段变更',
            type: 'warning'
          });
          _this.isSaveWDBG = true;
        } else {
          _this.isSaveWDBG = false;
        }
      });
    },
    subChange1: function subChange1(data) {
      var _this2 = this;
      this.searchForm.subnetOld = data.id;
      var params = {
        subnet: data.id,
        isUsed: 1
      };
      queryIpPoolCount(params).then(function (resp) {
        //   if (data.oldOrNew === 1) {
        _this2.searchForm.ipUsedCount = resp.data;
        if (_this2.searchForm.ipUsedCount === 0) {
          _this2.$message({
            message: '原网段已用地址数为零，不允许变更',
            type: 'warning'
          });
          _this2.isSaveWDBG = true;
        } else {
          _this2.isSaveWDBG = false;
          //   this.searchSwitchBySubnetId()
        }

        //   } else if (data.oldOrNew === 2) {
        //     this.wdbg.ipAvailableCount = resp.data
        //   }
      });
    },
    subChange2: function subChange2(data) {
      var _this3 = this;
      // this.searchForm.subnetNew = data.id
      var params = {
        subnet: data.id,
        isUsed: 0
      };
      queryIpPoolCount(params).then(function (resp1) {
        _this3.searchForm.ipAvailableCount = resp1.data;
      });
    },
    handleSubmit: function handleSubmit() {
      var _this4 = this;
      //   this.$emit('setVal', this.searchForm)

      if (this.searchForm.ipUsedCount >= this.searchForm.ipAvailableCount) {
        this.$message({
          message: '空闲地址小于或等于已用地址，无法保存',
          type: 'warning'
        });
        return;
      }
      if (this.searchForm.ipUsedCount === '0') {
        this.$message({
          message: '原网段已用地址数为0 ，不允许变更',
          type: 'warning'
        });
        return;
      }
      if (this.searchForm.subnetOld === this.searchForm.subnetNew) {
        this.$message({
          message: '选择的子网是同一个，请重新选择',
          type: 'warning'
        });
        return;
      }
      updateSubnet(this.searchForm).then(function (resp) {
        if (resp.code === 200) {
          _this4.$message({
            message: '网段变更成功',
            type: 'success'
          });
          _this4.$emit('close');
        } else {
          _this4.$message({
            message: '网段变更失败',
            type: 'error'
          });
        }
      });
    },
    handleCancel: function handleCancel() {
      this.$emit('close');
    },
    getDictList: function getDictList(code) {
      var _this5 = this;
      //加载字典
      _getDictList(code).then(function (res) {
        if (code === 'swState') {
          _this5.swStateList = res.data;
        } else if (code === 'Is802') {
          _this5.Is802List = res.data;
        } else if (code === 'snmpVersion') {
          _this5.snmpVersionList = res.data;
        } else if (code === 'isAccessSwitch') {
          _this5.isAccessSwitchList = res.data;
        }
      });
    },
    getDictCmdbList: function getDictCmdbList(ciId) {
      var _this6 = this;
      //加载字典
      _getDictCmdbList({
        ciId: ciId
      }).then(function (res) {
        if (ciId === '1082554947272704') {
          // 品牌
          _this6.brandList = res.data;
        } else if (ciId === '1082609011851264') {
          // 系列
          _this6.seriesList = res.data;
        } else if (ciId === '1082608047161344') {
          // 型号
          _this6.deviceModelList = res.data;
        } else if (ciId === '1083979207081984') {
          // 国家及地区
          _this6.maintenanceCountryList = res.data;
        }
      });
    },
    // 保存
    save: function save() {
      var _this7 = this;
      this.$refs.searchForm.validate(function (valid) {
        if (valid) {
          _this7.saveLoading = true;
          globalattrSave(_this7.searchForm).then(function (res) {
            _this7.saveLoading = false;
            _this7.$message({
              type: 'success',
              message: '保存成功！'
            });
            _this7.$emit('saveGlobalArrt');
          }).catch(function () {
            _this7.saveLoading = false;
          });
        }
      });
    }
  }
};
